  /* ============ motore sudoku ============ */
  var rnd = function(n){ return Math.floor(Math.random()*n); };
  function shuffle(a){
    for(var i=a.length-1;i>0;i--){ var j=rnd(i+1), t=a[i]; a[i]=a[j]; a[j]=t; }
    return a;
  }

  var peers = [];
  (function(){
    for(var i=0;i<81;i++){
      var r=Math.floor(i/9), c=i%9, br=r-r%3, bc=c-c%3, s={};
